<!doctype html><html lang="en"><head><base href="/Ordering/"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Portal | UniCanteen</title><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@600;700;900&family=Poppins:wght@300;400;600&display=swap" rel="stylesheet"><style>:root{--sidebar-bg:#1e293b;--accent:#2563eb;--accent-hover:#1d4ed8;--card-shadow:0 2px 10px rgba(0,0,0,.05)}*{box-sizing:border-box}body{margin:0;font-family:Poppins,sans-serif;background:#f1f5f9;color:#0f172a}.sidebar{width:230px;background:var(--sidebar-bg);color:#fff;height:100vh;position:fixed;display:flex;flex-direction:column;z-index:10}.logo-box{width:100%;padding:20px 0 5px;text-align:center;border-bottom:1px solid rgba(255,255,255,.06)}.logo-box img{width:125px;height:auto;border-radius:12px;object-fit:contain}.sidebar h2{margin:0;text-align:center;padding:1rem 0;border-bottom:1px solid rgba(255,255,255,.06);font-family:Montserrat}.nav-btn,.logout{width:calc(100% - 16px);margin:6px 8px;padding:.85rem 1.4rem;display:block;border:0;border-radius:8px;background:transparent;color:#cbd5e1;text-align:left;font:400 14px Poppins;cursor:pointer;text-decoration:none;transition:.15s}.nav-btn:hover,.nav-btn.active,.logout:hover{background:rgba(0,85,255,.12);color:#fff}.logout{margin-top:auto;margin-bottom:14px}.main{margin-left:230px;padding:1.5rem;height:100vh}.topbar{height:62px;background:#fff;border-radius:12px;padding:.8rem 1rem;margin-bottom:1rem;display:flex;align-items:center;justify-content:space-between;box-shadow:var(--card-shadow)}.topbar h2{margin:0;font:700 19px Montserrat}.topbar span{font-size:13px;color:#64748b}.content{height:calc(100vh - 102px);background:#fff;border-radius:12px;box-shadow:var(--card-shadow);overflow:hidden}.frame{width:100%;height:100%;border:0;background:#f1f5f9}@media(max-width:760px){.sidebar{position:static;width:100%;height:auto}.main{margin:0;height:calc(100vh - 310px);padding:1rem}}</style></head><body><aside class="sidebar"><div class="logo-box"><img src="assets/images/logo2.png" alt="School Logo"></div><h2>UniCanteen</h2><button class="nav-btn active" data-url="/Ordering/app/admin/admin_dashboard.php">Overview & Approvals</button><button class="nav-btn" data-url="/Ordering/app/admin/admin_users.php">User Management</button><button class="nav-btn" data-url="/Ordering/app/admin/admin_orders.php">Order Oversight</button><button class="nav-btn" data-url="/Ordering/app/admin/admin_operations.php">Operations & Moderation</button><button class="nav-btn" data-url="/Ordering/app/admin/admin_account_support.php">Account Support</button><a class="logout" href="/Ordering/app/auth/logout.php">Logout</a></aside><main class="main"><div class="topbar"><h2 id="title">Overview & Approvals</h2><span>Administrator: <?=htmlspecialchars($_SESSION['full_name']??'Admin')?></span></div><div class="content"><iframe class="frame" id="content" src="/Ordering/app/admin/admin_dashboard.php"></iframe></div></main><script>const frame=document.getElementById('content');function tidy(){try{const d=frame.contentDocument,s=d.querySelector('.side'),m=d.querySelector('.main');if(s)s.style.display='none';if(m){m.style.marginLeft='0';m.style.width='100%';}}catch(e){}}frame.addEventListener('load',tidy);document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav-btn').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('title').textContent=b.textContent;frame.src=b.dataset.url;});</script></body></html>
